// ListAlertsForRepo OAuth app tokens and personal access tokens (classic) need the `security_events` scope to use this endpoint. If this endpoint is only used with public repositories, the token can use the `public_repo` scope instead.
//
// Parameters:
//
//	owner: The account owner of the repository. The name is not case sensitive.
//	repo: The name of the repository without the `.git` extension. The name is
//	not case sensitive.
//	classification: A comma-separated list of vulnerability classifications. If
//	specified, only alerts for vulnerabilities with these classifications will
//	be returned. Can be: `malware`, `general`
//	state: A comma-separated list of states. If specified, only alerts with
//	these states will be returned. Can be: `auto_dismissed`, `dismissed`,
//	`fixed`, `open`
//	severity: A comma-separated list of severities. If specified, only alerts
//	with these severities will be returned. Can be: `low`, `medium`, `high`,
//	`critical`
//	ecosystem: A comma-separated list of ecosystems. If specified, only alerts
//	for these ecosystems will be returned. Can be: `composer`, `go`, `maven`,
//	`npm`, `nuget`, `pip`, `pub`, `rubygems`, `rust`
//	package_: A comma-separated list of package names. If specified, only alerts
//	for these packages will be returned.
//	manifest: A comma-separated list of full manifest paths. If specified, only
//	alerts for these manifests will be returned.
//	epssPercentage: CVE Exploit Prediction Scoring System (EPSS) percentage. Can
//	be specified as: - An exact number (`n`) - Comparators such as `>n`, `<n`,
//	`>=n`, `<=n` - A range like `n..n`, where `n` is a number from 0.0 to 1.0
//	Filters the list of alerts based on EPSS percentages. If specified, only
//	alerts with the provided EPSS percentages will be returned.
//	has: Filters the list of alerts based on whether the alert has the given
//	value. If specified, only alerts meeting this criterion will be returned.
//	Multiple `has` filters can be passed to filter for alerts that have all of
//	the values. Currently, only `patch` is supported.
//	assignee: Filter alerts by assignees. Provide a comma-separated list of user
//	handles (e.g., `octocat` or `octocat,hubot`) to return alerts assigned to
//	any of the specified users. Use `*` to list alerts with at least one
//	assignee or `none` to list alerts with no assignees.
//	scope: The scope of the vulnerable dependency. If specified, only alerts
//	with this scope will be returned.
//	relationship: A comma-separated list of relationships of the vulnerable
//	dependency to your project. If specified, only alerts with these
//	relationships will be returned. > [!NOTE] > We are rolling out support for
//	dependency relationship across ecosystems. This value will be "unknown" for
//	all dependencies in unsupported ecosystems.
//	sort: The property by which to sort the results. `created` means when the
//	alert was created. `updated` means when the alert's state last changed.
//	`epss_percentage` sorts alerts by the Exploit Prediction Scoring System
//	(EPSS) percentage.
//	direction: The direction to sort the results by.
//	before: A cursor, as given in the [Link
//	header](https://docs.github.com/rest/guides/using-pagination-in-the-rest-api
//	#using-link-headers). If specified, the query only searches for results
//	before this cursor. For more information, see "[Using pagination in the REST
//	API](https://docs.github.com/rest/using-the-rest-api/using-pagination-in-the
//	-rest-api)."
//	after: A cursor, as given in the [Link
//	header](https://docs.github.com/rest/guides/using-pagination-in-the-rest-api
//	#using-link-headers). If specified, the query only searches for results
//	after this cursor. For more information, see "[Using pagination in the REST
//	API](https://docs.github.com/rest/using-the-rest-api/using-pagination-in-the
//	-rest-api)."
//	perPage: The number of results per page (max 100). For more information, see
//	"[Using pagination in the REST
//	API](https://docs.github.com/rest/using-the-rest-api/using-pagination-in-the
//	-rest-api)."
func (sdk *DependabotNamespace) ListAlertsForRepo(ctx context.Context, params DependabotListAlertsForRepoParams, opts ...RequestOption) ([]DependabotAlert, error) {
	return DependabotListAlertsForRepo(ctx, sdk.config, params, opts...)
}

